import pulp

# Problem Data
num_trucks = 10
num_ops = 10

# Processing times P_{t,k}
P = [
    [7, 7, 10, 9, 5, 10, 8, 7, 4, 3],   # T1
    [2, 6, 2, 1, 4, 2, 10, 6, 9, 1],    # T2
    [1, 1, 1, 4, 2, 1, 8, 2, 5, 4],     # T3
    [1, 9, 10, 10, 7, 10, 8, 3, 7, 10], # T4
    [6, 10, 7, 7, 5, 4, 7, 7, 10, 7],   # T5
    [6, 6, 8, 10, 5, 10, 9, 2, 1, 2],   # T6
    [5, 7, 5, 2, 9, 10, 1, 1, 3, 4],    # T7
    [8, 10, 2, 9, 4, 9, 8, 3, 8, 10],   # T8
    [8, 10, 3, 7, 1, 9, 1, 9, 4, 9],    # T9
    [6, 4, 2, 7, 4, 3, 4, 8, 10, 7]     # T10
]

# Routes Route_{t,k}
Route = [
    ["DC2", "DC5", "DC8", "DC7", "DC3", "DC10", "DC4", "DC9", "DC6", "DC1"], # T1
    ["DC8", "DC5", "DC3", "DC1", "DC9", "DC2", "DC6", "DC4", "DC10", "DC7"], # T2
    ["DC5", "DC8", "DC7", "DC1", "DC2", "DC3", "DC6", "DC9", "DC4", "DC10"], # T3
    ["DC9", "DC6", "DC7", "DC2", "DC8", "DC5", "DC10", "DC4", "DC3", "DC1"], # T4
    ["DC9", "DC10", "DC2", "DC8", "DC5", "DC7", "DC3", "DC4", "DC1", "DC6"], # T5
    ["DC9", "DC4", "DC8", "DC1", "DC7", "DC5", "DC10", "DC3", "DC6", "DC2"], # T6
    ["DC5", "DC3", "DC10", "DC6", "DC2", "DC1", "DC8", "DC9", "DC4", "DC7"], # T7
    ["DC2", "DC7", "DC3", "DC6", "DC5", "DC9", "DC8", "DC1", "DC4", "DC10"], # T8
    ["DC6", "DC4", "DC3", "DC1", "DC8", "DC9", "DC7", "DC2", "DC5", "DC10"], # T9
    ["DC10", "DC6", "DC1", "DC7", "DC2", "DC8", "DC5", "DC4", "DC3", "DC9"]  # T10
]

# Initialize Model
model = pulp.LpProblem("TruckScheduling", pulp.LpMinimize)

# Decision Variables
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

S = {}
C = {}
for t in range(num_trucks):
    for k in range(num_ops):
        S[(t, k)] = pulp.LpVariable(f"S_{t}_{k}", lowBound=0, cat='Continuous')
        C[(t, k)] = pulp.LpVariable(f"C_{t}_{k}", lowBound=0, cat='Continuous')

x = {}
for t in range(num_trucks):
    for k in range(num_ops):
        for u in range(num_trucks):
            for l in range(num_ops):
                # Only create binary variables for operations at the same distribution center
                if Route[t][k] == Route[u][l]:
                    x[(t, k, u, l)] = pulp.LpVariable(f"x_{t}_{k}_{u}_{l}", cat='Binary')

# Objective Function
model += C_max, "Minimize_Makespan"

# Constraints

# R1: The makespan C_max must be greater than or equal to the completion time of the last operation for every truck
for t in range(num_trucks):
    model += C_max >= C[(t, num_ops - 1)], f"R1_makespan_truck_{t}"

# R2: The start time of the first operation for each truck must be greater than or equal to 0
for t in range(num_trucks):
    model += S[(t, 0)] >= 0, f"R2_start_time_truck_{t}"

# R3: For each truck, the start time of an operation must be greater than or equal to the completion time of the previous operation in its route
for t in range(num_trucks):
    for k in range(1, num_ops):
        model += S[(t, k)] >= C[(t, k - 1)], f"R3_sequence_truck_{t}_op_{k}"

# R4: For any two operations (t,k) and (u,l) that occur at the same distribution center, 
# either (t,k) must finish before (u,l) starts, or (u,l) must finish before (t,k) starts
# Note: We iterate over all pairs and check if they share a DC.
M = 10000  # Big-M value
for t in range(num_trucks):
    for k in range(num_ops):
        for u in range(num_trucks):
            for l in range(num_ops):
                if Route[t][k] == Route[u][l]:
                    # Avoid redundant constraints for the same operation
                    if t == u and k == l:
                        continue

                    # Constraint: C_{t,k} <= S_{u,l} + M * (1 - x_{t,k,u,l})
                    model += C[(t, k)] <= S[(u, l)] + M * (1 - x[(t, k, u, l)]), f"R4_disj_{t}_{k}_before_{u}_{l}"

# R5: Operations cannot be interrupted (start time plus processing time equals completion time)
for t in range(num_trucks):
    for k in range(num_ops):
        model += C[(t, k)] == S[(t, k)] + P[t][k], f"R5_duration_truck_{t}_op_{k}"

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

import pulp

# Parameters
# P_t_k: Processing times for truck t, operation k
P = [
    [2, 1, 1, 2, 6, 8],   # T1
    [4, 3, 9, 9, 2, 9],   # T2
    [8, 7, 5, 1, 10, 3],  # T3
    [2, 10, 7, 6, 4, 9],  # T4
    [9, 8, 9, 7, 8, 5],   # T5
    [8, 2, 2, 8, 7, 10]   # T6
]

# D_t_k: Dock indices for truck t, operation k
D = [
    [5, 6, 1, 2, 4, 3],   # T1
    [3, 1, 4, 2, 6, 5],   # T2
    [2, 1, 6, 3, 4, 5],   # T3
    [4, 2, 6, 3, 1, 5],   # T4
    [4, 1, 6, 3, 5, 2],   # T5
    [2, 6, 3, 1, 5, 4]    # T6
]

# Sets
Trucks = range(6)
Ops = range(6)

# Initialize Model
model = pulp.LpProblem("TruckDockScheduling", pulp.LpMinimize)

# Decision Variables
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

S = {}
C = {}
for t in Trucks:
    for k in Ops:
        S[t, k] = pulp.LpVariable(f"S_{t}_{k}", lowBound=0, cat='Continuous')
        C[t, k] = pulp.LpVariable(f"C_{t}_{k}", lowBound=0, cat='Continuous')

x = {}
for t in Trucks:
    for u in Trucks:
        if t != u:
            for k in Ops:
                for l in Ops:
                    x[t, k, u, l] = pulp.LpVariable(f"x_{t}_{k}_{u}_{l}", cat='Binary')

# Objective Function
model += C_max, "Minimize_Makespan"

# Constraints

# R1: The completion time of an operation must be equal to its start time plus its processing duration
for t in Trucks:
    for k in Ops:
        model += C[t, k] == S[t, k] + P[t][k], f"R1_completion_time_{t}_{k}"

# R2: The start time of the first operation for each truck must be greater than or equal to zero
for t in Trucks:
    model += S[t, 0] >= 0, f"R2_start_time_{t}"

# R3: The start time of a subsequent operation for a truck must be greater than or equal to the completion time of the immediately preceding operation for that truck
for t in Trucks:
    for k in range(1, 6):
        model += S[t, k] >= C[t, k-1], f"R3_sequence_{t}_{k}"

# R4: For any two operations from different trucks that require the same dock, one must start after the other finishes (disjunctive constraint)
M = 1000  # Big M value
for t in Trucks:
    for u in Trucks:
        if t < u: # Avoid duplicate pairs
            for k in Ops:
                for l in Ops:
                    if D[t][k] == D[u][l]:
                        # If x[t,k,u,l] = 1, then C[t,k] <= S[u,l]
                        model += C[t, k] <= S[u, l] + M * (1 - x[t, k, u, l]), f"R4_disjunctive_1_{t}_{k}_{u}_{l}"
                        # If x[t,k,u,l] = 0, then C[u,l] <= S[t,k]
                        model += C[u, l] <= S[t, k] + M * x[t, k, u, l], f"R4_disjunctive_2_{t}_{k}_{u}_{l}"

# R5: The makespan must be greater than or equal to the completion time of the last operation for every truck
for t in Trucks:
    model += C_max >= C[t, 5], f"R5_makespan_{t}"

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))
